<?php require_once __DIR__.'/includes/functions.php';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){check_csrf();$act=$_POST['action']??'';if($act==='add'){$id=(string)($_POST['id']??'');$p=product($id);if($p){$storage=in_array($_POST['storage']??'', $p['storage'],true)?$_POST['storage']:$p['storage'][0];$color=in_array($_POST['color']??'', $p['colors'],true)?$_POST['color']:$p['colors'][0];$key=$id.'|'.$storage.'|'.$color;$_SESSION['cart'][$key]=min(10,((int)($_SESSION['cart'][$key]??0))+1);}}elseif($act==='update'){foreach($_POST['qty']??[] as $key=>$qty)if(isset($_SESSION['cart'][$key])){if((int)$qty<1)unset($_SESSION['cart'][$key]);else $_SESSION['cart'][$key]=min(10,(int)$qty);}}elseif($act==='remove'){unset($_SESSION['cart'][(string)($_POST['key']??'')]);}header('Location: /cart.php');exit;} $items=cart_data();$meta=page_meta('Your Bag | iPhone Deals');require __DIR__.'/includes/header.php';?>
<section class="wrap"><h1 class="page-title">Your bag</h1><?php if(!$items):?><div class="empty"><h2>Your bag is ready for something good.</h2><a class="button button-dark" href="/deals.php">Browse iPhone deals</a></div><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="update"><?php foreach($items as $i):?><div class="cart-row"><div><b><?=e($i['p']['name'])?></b><div class="muted"><?=e($i['p']['condition'])?> · <?=e($i['storage'])?> · <?=e($i['color'])?></div><div class="saving"><?=$i['p']['discount']?>% OFF · Save <?=money(($i['p']['original']-$i['p']['price'])*$i['qty'])?></div></div><div><s><?=money($i['p']['original'])?></s><br><b><?=money($i['p']['price'])?></b></div><label>Qty <input style="width:65px" type="number" min="1" max="10" name="qty[<?=e($i['key'])?>]" value="<?=$i['qty']?>"></label><div><button class="button button-light" form="remove-<?=md5($i['key'])?>">Remove</button></div></div><?php endforeach;?><button class="button button-light" type="submit">Update bag</button></form><?php foreach($items as $i):?><form id="remove-<?=md5($i['key'])?>" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="key" value="<?=e($i['key'])?>"></form><?php endforeach;?><aside class="cart-summary"><h2>Order summary</h2><div class="summary-line"><span>Subtotal</span><b><?=money(array_sum(array_map(fn($i)=>$i['p']['original']*$i['qty'],$items)))?></b></div><div class="summary-line"><span>Discount</span><b class="saving">−<?=money(array_sum(array_map(fn($i)=>($i['p']['original']-$i['p']['price'])*$i['qty'],$items)))?></b></div><div class="summary-line"><span>Shipping</span><span>Calculated at checkout</span></div><div class="summary-line"><span>Estimated tax</span><span>Calculated at checkout</span></div><hr><div class="summary-line"><b>Current total</b><b><?=money(cart_total())?></b></div><a class="button button-dark full" href="/checkout.php">Continue to checkout</a></aside><?php endif;?></section><?php require __DIR__.'/includes/footer.php';?>
